INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','past-habits','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"past-habits","title":"Past habits: used to, would and getting used to","level":"B1","order":35,"summary":"Distinguish a former habit from a familiar experience and from the process of adapting.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Former habits and states","Repeated past actions with would","Being accustomed to something","The process of adapting"],"rules":[{"title":"Former habits and states","explanation":"Use **used to + base verb** for a past habit or state that contrasts with now. Used to can describe actions and states. In standard written questions and negatives after did, use **use to**.","pattern":"I **used to live** here. / Did you **use to live** here?","commonMistakes":["Used to is not a normal present-habit form. For habits now, use present simple."],"examples":["Complete a former habit: I used to **prepare** the visitor guide, but I do not do that now.","Complete a former habit: I used to **restore** the old portrait, but I do not do that now."],"skill":"form"},{"title":"Repeated past actions with would","explanation":"Would can recall repeated actions within an established past period. It normally needs a clear past setting and does not usually replace used to for a continuing state such as owning a house.","pattern":"When we were children, we **would visit** every summer.","commonMistakes":["We would own a cottage does not normally describe simple past ownership."],"examples":["Use did in the negative: I did not **use to prepare** the visitor guide in my old job.","Use did in the negative: I did not **use to restore** the old portrait in my old job."],"skill":"meaning"},{"title":"Being accustomed to something","explanation":"In **be used to**, used is an adjective and to is a preposition. Follow it with a noun or an -ing form. It means familiar or accustomed, and be can refer to present, past or future.","pattern":"She **is used to working** at night.","commonMistakes":["Is used to work does not mean that she is accustomed to working."],"examples":["I am familiar with the task: I am used to **preparing** the visitor guide.","I am familiar with the task: I am used to **restoring** the old portrait."],"skill":"contrast"},{"title":"The process of adapting","explanation":"**Get used to + noun / -ing** describes becoming accustomed. The tense belongs to get: am getting used to, got used to, will get used to. This is distinct from a discontinued habit.","pattern":"I’m **getting used to driving** on the left.","commonMistakes":["Do not add an extra be after get; get used to already expresses the change."],"examples":["Recall a repeated action with would: In my old job, I would **prepare** the visitor guide every week.","Recall a repeated action with would: In my old job, I would **restore** the old portrait every week."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits","bc-used-to"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"57d2c1da-2096-5a68-ab7b-994dab5b5fec","topicSlug":"past-habits","level":"B1","prompt":"Complete a former habit: I used to ____ the visitor guide, but I do not do that now.","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepare"},{"id":"D","text":"preparing"}],"answerId":"C","hint":"Here used to contrasts a past routine with now.","explanation":"The discontinued-habit pattern is **used to + prepare**, using the base verb.","keywords":["former-habit"],"skill":"former-habit","contextKey":"past-habits-1","fingerprint":"5122322c67dbe22a4c8991b21fabb078b39096f1eff5db994c62961ae8a354e7","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Here used to contrasts a past routine with now.","The discontinued-habit pattern is **used to + prepare**, using the base verb.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Used to already marks the past habit; the following verb stays in the base form.","B":"To is already present; do not repeat it.","C":"The discontinued-habit pattern is **used to + prepare**, using the base verb.","D":"The -ing form belongs after be/get used to, not after past-habit used to."}}},{"id":"41f0a49c-bfa8-5351-a20f-fded4f62957c","topicSlug":"past-habits","level":"B1","prompt":"Use did in the negative: I did not ____ the visitor guide in my old job.","choices":[{"id":"A","text":"using to prepare"},{"id":"B","text":"use to prepare"},{"id":"C","text":"used to prepare"},{"id":"D","text":"use to preparing"}],"answerId":"B","hint":"The past marker is already on **did**.","explanation":"After **did not**, standard written English uses **use to prepare**.","keywords":["habit-negative"],"skill":"habit-negative","contextKey":"past-habits-1","fingerprint":"b84a8119e2b9bbb2103a857f13fc7b6da416f5e06ddbeadbf79335cf2333d174","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past marker is already on **did**.","After **did not**, standard written English uses **use to prepare**.","Choose **use to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did requires the base form use, not using.","B":"After **did not**, standard written English uses **use to prepare**.","C":"After did, the recommended standard written form is use to, without -d.","D":"Past-habit use to takes the base verb."}}},{"id":"003bff75-54b3-5786-ad54-488a533f5023","topicSlug":"past-habits","level":"B1","prompt":"I am familiar with the task: I am used to ____ the visitor guide.","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"prepare"},{"id":"C","text":"prepared"},{"id":"D","text":"to prepare"}],"answerId":"A","hint":"The word **am** changes the construction: this is familiarity, not a former habit.","explanation":"In **am used to**, to is a preposition, so the following verb is **preparing**.","keywords":["accustomed-state"],"skill":"accustomed-state","contextKey":"past-habits-1","fingerprint":"cc43e0ef73d495aee1bb1a21a17871dd460efdfedf3d3bce727c02660fdb694b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The word **am** changes the construction: this is familiarity, not a former habit.","In **am used to**, to is a preposition, so the following verb is **preparing**.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"In **am used to**, to is a preposition, so the following verb is **preparing**.","B":"The base verb belongs in the former-habit pattern, not after am used to.","C":"A past participle does not name the activity after this preposition.","D":"Do not put a to-infinitive after the preposition to in this pattern."}}},{"id":"cc661899-b278-5a88-a206-5994a39454fa","topicSlug":"past-habits","level":"B1","prompt":"Recall a repeated action with would: In my old job, I would ____ the visitor guide every week.","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"prepared"},{"id":"C","text":"to prepare"},{"id":"D","text":"prepare"}],"answerId":"D","hint":"The context supplies a past routine; **would** still takes the base form.","explanation":"Would takes the base verb **prepare**. The old job and every week establish a repeated past action.","keywords":["repeated-past-action"],"skill":"repeated-past-action","contextKey":"past-habits-1","fingerprint":"cdae02f444553864a399e5765aaee8de23862f43ce700fb8b763391dc8a94a1e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The context supplies a past routine; **would** still takes the base form.","Would takes the base verb **prepare**. The old job and every week establish a repeated past action.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would alone cannot take an -ing form.","B":"Would takes a base verb, not a past form.","C":"Would takes a bare infinitive without to.","D":"Would takes the base verb **prepare**. The old job and every week establish a repeated past action."}}},{"id":"876d0570-1d6c-5d6d-adc5-6efe1ee0b7a6","topicSlug":"past-habits","level":"B1","prompt":"Complete a former habit: I used to ____ the old portrait, but I do not do that now.","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"restoring"},{"id":"D","text":"restored"}],"answerId":"B","hint":"Here used to contrasts a past routine with now.","explanation":"The discontinued-habit pattern is **used to + restore**, using the base verb.","keywords":["former-habit"],"skill":"former-habit","contextKey":"past-habits-2","fingerprint":"2723b2afb3c88ff25e4a82bc4b017fd8b83a9a0d5a901e44a1446672630d4746","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Here used to contrasts a past routine with now.","The discontinued-habit pattern is **used to + restore**, using the base verb.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"To is already present; do not repeat it.","B":"The discontinued-habit pattern is **used to + restore**, using the base verb.","C":"The -ing form belongs after be/get used to, not after past-habit used to.","D":"Used to already marks the past habit; the following verb stays in the base form."}}},{"id":"99061d4e-1a90-5b11-a460-e8b13e368e4f","topicSlug":"past-habits","level":"B1","prompt":"Use did in the negative: I did not ____ the old portrait in my old job.","choices":[{"id":"A","text":"use to restore"},{"id":"B","text":"used to restore"},{"id":"C","text":"use to restoring"},{"id":"D","text":"using to restore"}],"answerId":"A","hint":"The past marker is already on **did**.","explanation":"After **did not**, standard written English uses **use to restore**.","keywords":["habit-negative"],"skill":"habit-negative","contextKey":"past-habits-2","fingerprint":"9c148cd4754f8b902fdb17153816abb18688887babc1648aa74a791ea1dfdf79","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past marker is already on **did**.","After **did not**, standard written English uses **use to restore**.","Choose **use to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After **did not**, standard written English uses **use to restore**.","B":"After did, the recommended standard written form is use to, without -d.","C":"Past-habit use to takes the base verb.","D":"Did requires the base form use, not using."}}},{"id":"25d354cf-cb8d-5c4f-af2e-de732078053e","topicSlug":"past-habits","level":"B1","prompt":"I am familiar with the task: I am used to ____ the old portrait.","choices":[{"id":"A","text":"restore"},{"id":"B","text":"restored"},{"id":"C","text":"to restore"},{"id":"D","text":"restoring"}],"answerId":"D","hint":"The word **am** changes the construction: this is familiarity, not a former habit.","explanation":"In **am used to**, to is a preposition, so the following verb is **restoring**.","keywords":["accustomed-state"],"skill":"accustomed-state","contextKey":"past-habits-2","fingerprint":"989ce63bd085cc81907d34621250ae73690570725d450c1a72bd4df739003f1a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-habits"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The word **am** changes the construction: this is familiarity, not a former habit.","In **am used to**, to is a preposition, so the following verb is **restoring**.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The base verb belongs in the former-habit pattern, not after am used to.","B":"A past participle does not name the activity after this preposition.","C":"Do not put a to-infinitive after the preposition to in this pattern.","D":"In **am used to**, to is a preposition, so the following verb is **restoring**."}}},{"id":"8f2a1e21-3a51-58c5-a5c5-551d03dea76f","topicSlug":"past-habits","level":"B1","prompt":"Recall a repeated action with would: In my old job, I would ____ the old portrait every week.","choices":[{"id":"A","text":"restore"},{"id":"B","text":"restoring"},{"id":"C","text":"restored"},{"id":"D","text":"to restore"}],"answerId":"A","hint":"The context supplies a past routine; **would** still takes the base form.","explanation":"Would takes the base verb **restore**. The old job and every week establish a repeated past action.","keywords":["repeated-past-action"],"skill":"repeated-past-action","contextKey":"past-habits-2","fingerprint":"2674a529af3850367c3674621e6226d6bf274604d4aa089756946e56e13a8c3b","source":"seed","p